def validation_message(error: ValidationError) -> str:
    """connectors/executor.py `validation_message`."""
    problems = [
        f"{'.'.join(str(p) for p in item['loc']) or 'input'}: {item['msg']}" for item in error.errors()[:5]
    ]
    return "Invalid arguments. " + "; ".join(problems)


def validated(model, data) -> dict:
    try:
        return {"ok": model.model_validate(data).model_dump()}
    except ValidationError as error:
        return {"error": validation_message(error)}
    except Exception as error:  # noqa: BLE001
        return {"raises": type(error).__name__}


def outcome(function, *args, **kwargs) -> dict:
    try:
        return {"ok": function(*args, **kwargs)}
    except OperationError as error:
        return {"code": error.code, "message": error.message}
    except Exception as error:  # noqa: BLE001
        return {"raises": type(error).__name__, "message": str(error)}


def raised(error: BaseException) -> str:
    """The Python exception classes a port must tell apart, most specific first."""
    for kind in (UnicodeDecodeError, UnicodeEncodeError, UnicodeError, LookupError, ValueError, IndexError, TypeError):
        if isinstance(error, kind):
            return kind.__name__
    return "other:" + type(error).__name__


# The shared base: how Google's 403s are read, and path segments.


def base_cases() -> dict:
    import httpx

    def body(*errors, details=None, key="errors") -> str:
        error = {"code": 403, "message": "no", key: list(errors)}
        if details is not None:
            error["details"] = details
        return json.dumps({"error": error})

    bodies = [
        body({"reason": "rateLimitExceeded"}),
        body({"reason": "userRateLimitExceeded"}),
        body({"reason": "accessNotConfigured"}),
        body({"reason": "insufficientPermissions"}),
        body({"reason": "exportSizeLimitExceeded"}),
        body({"reason": "insufficientPermissions"}, details=[{"reason": "SERVICE_DISABLED", "domain": "x"}]),
        body({"reason": "insufficientPermissions"}, {"reason": "rateLimitExceeded"}),
        body({"reason": "exportSizeLimitExceeded"}, {"reason": "accessNotConfigured"}),
        body(details=[{"@type": "type.googleapis.com/google.rpc.ErrorInfo", "reason": "SERVICE_DISABLED"}]),
        body({"reason": "rateLimitExceeded"}, {"reason": ["x"]}),
        body({"reason": "rateLimitExceeded"}, {"reason": {"a": 1}}),
        body({"reason": "rateLimitExceeded"}, {"reason": 5}),
        body({"reason": "rateLimitExceeded"}, {"reason": None}),
        body({"reason": "rateLimitExceeded"}, {"noreason": 1}),
        body({"reason": "rateLimitExceeded"}, "text"),
        body({"reason": "rateLimitExceeded"}, ["x"]),
        body({"reason": "rateLimitExceeded"}, None),
        '{"error": {"errors": null}}',
        '{"error": {"errors": 5}}',
        '{"error": {"errors": "ab"}}',
        '{"error": {"errors": ""}}',
        '{"error": {"errors": {}}}',
        '{"error": {"errors": {"reason": "rateLimitExceeded"}}}',
        '{"error": {"errors": [], "details": [{"reason": "rateLimitExceeded"}]}}',
        '{"error": {"details": null}}',
        '{"error": {"details": {"reason": "rateLimitExceeded"}}}',
        '{"error": "rateLimitExceeded"}',
        '{"error": ["rateLimitExceeded"]}',
        '{"error": null}',
        '{"error": {}}',
        '{"errors": [{"reason": "rateLimitExceeded"}]}',
        '["rateLimitExceeded"]',
        '"rateLimitExceeded"',
        "null",
        "5",
        "{}",
        "",
        "not json",
        '{"error": {"errors": [{"reason": "rateLimitExceeded"}]}',
        '{"error": {"errors": [{"reason": "ratelimitexceeded"}]}}',
        '{"error": {"errors": [{"reason": "rateLimitExceeded "}]}}',
        '{"error": {"errors": [{"reason": "\\u0072ateLimitExceeded"}]}}',
        '{"error": {"errors": [{"reason": "rateLimitExceeded", "reason": "x"}]}}',
        '{"error": {"errors": [{"reason": "x", "reason": "rateLimitExceeded"}]}}',
    ]
    found = {}
    for text in bodies:
        response = httpx.Response(403, content=text.encode())
        error = google.forbidden("Google Drive", response)
        found[text] = {"reasons": sorted(google._reasons(response)), "code": error.code, "message": error.message}
    segments = {
        text: google.segment(text)
        for text in ["primary", "a@b.com", "de.german#holiday@group.v.calendar.google.com", "a b", "ä", "😀", "a/b", "%41", "a~b-c_d.e", "!*'();:@&=+$,/?#[]"]
    }
    return {"forbidden": found, "segments": segments}


# Dates and times.


def iso_samples() -> list[str]:
    years = ["0000", "0001", "2024", "2026", "9999", "1900", "2000", "2100"]
    months = ["00", "01", "02", "04", "12", "13", "99"]
    days = ["00", "01", "28", "29", "30", "31", "32", "99"]
    hours = ["00", "09", "23", "24", "25", "99"]
    minutes = ["00", "30", "59", "60", "99"]
    seconds = ["", ":00", ":30", ":59", ":60", ":99"]
    fractions = ["", ".0", ".5", ".000001", ".999999", ".123", ".000000"]
    offsets = ["Z", "+00:00", "+02:00", "-05:30", "+23:59", "+23:60", "+24:00", "-24:00", "+00:99", "-23:59", "+99:99", "+12:00"]
    found = set()
    for _ in range(ISO_RANDOM):
        second = RANDOM.choice(seconds)
        fraction = RANDOM.choice(fractions) if second else ""
        found.add(
            f"{RANDOM.choice(years)}-{RANDOM.choice(months)}-{RANDOM.choice(days)}T"
            f"{RANDOM.choice(hours)}:{RANDOM.choice(minutes)}{second}{fraction}{RANDOM.choice(offsets)}"
        )
    for _ in range(ISO_DATES):
        found.add(f"{RANDOM.choice(years)}-{RANDOM.choice(months)}-{RANDOM.choice(days)}")
    found |= {
        "2026-10-02T14:00:00+02:00",
        "2026-10-02T14:00+02:00",
        "2026-10-02T14:00:00.1234567+02:00",
        "2026-10-02T14:00:00,5+02:00",
        "2026-10-02T14:00:00z",
        "2026-10-02t14:00:00Z",
        "2026-10-02 14:00:00Z",
        "2026-10-02T14:00:00",
        "2026-10-02T14:00:00+0200",
        "2026-12-31T24:00:00Z",
        "9999-12-31T24:00:00Z",
        "2024-02-29T24:00:00+01:00",
        "2026-02-28T24:00:00.000000Z",
        "2026-02-28T24:00:00.000001Z",
        "2026-02-28T24:00:01Z",
        "2026-02-28T24:01Z",
        "2026-02-30T24:00Z",
        "2026-13-30T24:00Z",
        "٢٠٢٦-١٠-٠٢T14:00:00Z",
        "2026-10-02T١٤:00:00Z",
        "٢٠٢٦-١٠-٠٢",
        "2026-1-02",
        "26-10-02",
        "2026-10-02",
        "",
        "2026-10-02T14:00:00+02:00\n",
    }
    return sorted(found)


def date_times() -> dict:
    samples = iso_samples()
    return {
        "date_time": {value: outcome(calendar._date_time, value) for value in samples},
        "date_or_date_time": {value: outcome(calendar._date_or_date_time, value) for value in samples},
    }


