def pick(alphabet, low: int, high: int) -> str:
    return "".join(RANDOM.choice(alphabet) for _ in range(RANDOM.randint(low, high)))


def base64_cases() -> list[dict]:
    """`b64decode(..., validate=True)` after Gmail's padding, and `base64mime.decode` (lax) after header padding."""
    alphabet = list("ABCDEFabcdef0123456789+/-_=") + ["=="] * 2 + [" ", "\n", "!", "ä", "."]
    samples = {"", "=", "==", "a", "ab", "abc", "abcd", "ab==", "ab=c", "a===", "=ab", "abc=", "ab=", "YQ", "YQ==",
               "YWI", "YWJj", "Y-_/", "Y+/=", "YW Jj", "YWJj\n", "YQ==YQ==", "YQ=a", "aGVsbG8gd29ybGQ", "ä", "YQ=="}
    for _ in range(BASE64_RANDOM):
        samples.add(pick(alphabet, 0, 12))
    found = []
    for text in sorted(samples):
        padded = text + "=" * (-len(text) % 4)
        try:
            strict = base64.b64decode(padded, altchars=b"-_", validate=True).hex()
        except (binascii.Error, ValueError) as error:
            strict = {"error": type(error).__name__}
        pad = len(text) % 4
        lax_text = text + ("==="[: 4 - pad] if pad else "")
        try:
            lax = binascii.a2b_base64(lax_text.encode("raw-unicode-escape")).hex()
        except binascii.Error:
            lax = {"error": "Error"}
        found.append({"text": text, "strict": strict, "lax": lax})
    return found


