def charset_cases() -> dict:
    """Which of the Encoding Standard's labels Python's codec registry has (as a text encoding): a label it lacks is a defect in an address header."""
    known = []
    for label in WHATWG_LABELS:
        try:
            if codecs.lookup(label)._is_text_encoding:
                known.append(label)
        except LookupError:
            pass
    return {"labels": WHATWG_LABELS, "python": known}


