def header_cases() -> list[dict]:
    found = []
    for value in HEADER_TEXTS:
        try:
            result = {"ok": mime.header_text(value)}
        except BaseException as error:  # noqa: BLE001
            result = {"error": raised(error)}
        found.append({"value": value, **result})
    return found


def content_type_cases() -> list[dict]:
    values = [
        ("text/plain; charset=utf-8", None),
        ("text/plain; charset=\"UTF-8\"", None),
        ("text/plain; CHARSET=iso-8859-1", None),
        ("text/plain;charset=x-nope", None),
        ("text/plain; charset*=utf-8''latin-1", None),
        ("text/plain; charset*=''utf-8", None),
        ("text/plain; charset*0=utf; charset*1=-8", None),
        ("text/plain; charset*=bogus''utf-8", None),
        ("text/plain; charset=\"ut\\\"f\"", None),
        ("text/plain; charset=é", None),
        ("text/plain; charset=", None),
        ("text/plain; charset", None),
        ("text/plain", None),
        ("text/plain; a=\"x;y\"; charset=utf-8", None),
        ("text/plain; charset=utf-8; charset=latin-1", None),
        ("multipart/related; start=\"<root@x>\"", None),
        ("multipart/related; start=<root@x>", None),
        ("multipart/related; START=\"<a@b>\"; type=text/html", None),
        ("multipart/related; start*=utf-8''%3Croot%40x%3E", None),
        (None, "attachment; filename=\"plan.pdf\""),
        (None, "Inline"),
        (None, " ATTACHMENT ;"),
        (None, "attachment\udc80"),
        (None, ""),
        ("text/plain; charset=utf-8\udcff", None),
    ]
    found = []
    for content_type, disposition in values:
        headers = []
        if content_type is not None:
            headers.append({"name": "Content-Type", "value": content_type})
        if disposition is not None:
            headers.append({"name": "content-disposition", "value": disposition})
        part = Part.model_validate({"mimeType": "text/plain", "headers": headers})
        result = {}
        for key, call in (
            ("charset", lambda: mime._content_type(part).get_content_charset()),
            ("disposition", lambda: mime._content_type(part).get_content_disposition()),
            ("start", lambda: mime._content_type(part).get_param("start")),
        ):
            try:
                value = call()
                result[key] = {"ok": list(value) if isinstance(value, tuple) else value}
            except BaseException as error:  # noqa: BLE001
                result[key] = {"error": raised(error)}
        found.append({"headers": headers, **result})
    return found


def b64(text: str, charset: str = "utf-8") -> str:
    return base64.urlsafe_b64encode(text.encode(charset)).decode().rstrip("=")


def text_part(text: str, mime_type: str = "text/plain", charset: str = "utf-8") -> dict:
    return {
        "mimeType": mime_type,
        "headers": [{"name": "Content-Type", "value": f"{mime_type}; charset={charset}"}],
        "body": {"size": len(text), "data": b64(text, charset)},
    }


