def address_header_cases() -> list[dict]:
    pieces = ["a", "grace", "@", "example.com", "Example.COM", ".", ",", ";", ":", "<", ">", "(", ")", '"', "\\",
              " ", "\t", "[", "]", "=?utf-8?q?x?=", "Gräce", "x@y.org", "<g@example.com>", "Team:", "b.example"]
    values = list(ADDRESS_HEADERS)
    seen = set(values)
    while len(values) < len(ADDRESS_HEADERS) + ADDRESSES_RANDOM:
        value = "".join(RANDOM.choice(pieces) for _ in range(RANDOM.randint(1, 9)))
        if value not in seen:
            seen.add(value)
            values.append(value)
    found = []
    for value in values:
        try:
            result = {"ok": mime.mailboxes([value])}
        except BaseException as error:  # noqa: BLE001
            result = {"error": raised(error)}
        try:
            header = default_policy.header_factory("reply-to", value)
            parsed = {
                "defects": len(header.defects),
                "addresses": [[a.display_name, a.username, a.domain, a.addr_spec] for a in header.addresses],
                "str": str(header),
            }
        except BaseException as error:  # noqa: BLE001
            parsed = {"error": raised(error)}
        found.append({"value": value, "mailboxes": result, "header": parsed})
    return found


