def html_cases() -> list[dict]:
    pieces = ["<p>", "</p>", "<a href='https://e.com/x'>", "</a>", "<b>", "</b>", "<li>", "<ul>", "</ul>", "<ol>",
              "<script>", "</script>", "<pre>", "</pre>", "&amp;", "&lt;", "<!--", "-->", "<br>", "text", " ", "\n",
              "<img alt='i'>", "<h3>", "</h3>", "<td>", "<tr>", "<table>", "<code>", "</code>", "<", ">", "&", "x y",
              "<style>", "</style>", "<title>", "</title>", "<blockquote>", "<hr>", "\t", "é", "<a href='/r'>", "<em>"]
    values = list(HTML)
    seen = set(values)
    while len(values) < len(HTML) + HTML_RANDOM:
        value = "".join(RANDOM.choice(pieces) for _ in range(RANDOM.randint(1, 14)))
        if value not in seen:
            seen.add(value)
            values.append(value)
    found = []
    for value in values:
        text, title = markdown.html_to_text(value, "")
        found.append({"html": value, "text": text, "title": title})
    return found


